package captiveportal

import (
	"archive/zip"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"regexp"
	"strings"

	coreapi "opnsense-cli/opnsense/api"
)

// Template is a custom portal page of Services > Captive Portal > Templates (api/captiveportal/template): a zip
// of the files that differ from the default template (index.html, css, images, ...). Zones refer to it by uuid
type Template struct {
	Uuid string `json:"uuid"`
	// FileId identifies the template content (generated by OPNsense), the download uses it
	FileId string `json:"fileid"`
	Name   string `json:"name"`
	// Content is the stored zip, base64 encoded (only the files that differ from the default template)
	Content string `json:"content"`
}

// templateNamePattern is what OPNsense accepts as template name: letters, digits, whitespace, . , _ and any
// non-ASCII character (no dashes)
var templateNamePattern = regexp.MustCompile(`^[\t\n\v\f\r 0-9a-zA-Z.,_\x{00A0}-\x{FFFF}]{1,255}$`)

// TemplateValidateName checks a template name like OPNsense does
func TemplateValidateName(name string) error {
	if !templateNamePattern.MatchString(name) {
		return fmt.Errorf("invalid template name %q: 1 to 255 letters, digits, spaces, dots, commas or underscores (no dashes)", name)
	}
	return nil
}

func templateName(uuid string) string {
	return "captive portal template " + uuid
}

// TemplateList returns the templates, searchPhrase is a substring match over all columns ("" for all)
func (opn *CaptivePortalApi) TemplateList(searchPhrase string) ([]Template, error) {
	return coreapi.Search[Template](opn.OPNsense, opn.endpoint("template", "search_templates"), searchPhrase)
}

// TemplateGet returns the template with the given uuid or a *NotFoundError
func (opn *CaptivePortalApi) TemplateGet(uuid string) (Template, error) {
	var templates, err = opn.TemplateList("")
	if err != nil {
		return Template{}, err
	}
	for _, template := range templates {
		if strings.EqualFold(template.Uuid, uuid) {
			return template, nil
		}
	}
	return Template{}, &coreapi.NotFoundError{Name: templateName(uuid)}
}

// TemplateGetByName returns the template with exactly this name (OPNsense matches names case-sensitively when
// saving) or a *NotFoundError
func (opn *CaptivePortalApi) TemplateGetByName(name string) (Template, error) {
	var templates, err = opn.TemplateList("")
	if err != nil {
		return Template{}, err
	}
	for _, template := range templates {
		if template.Name == name {
			return template, nil
		}
	}
	return Template{}, &coreapi.NotFoundError{Name: fmt.Sprintf("captive portal template %q", name)}
}

// TemplateDownload returns the complete template as zip: the files of the template with this file id over the
// default template, the default template for fileId "". OPNsense answers an unknown file id with the default
// template, so callers should take the file id from TemplateList
func (opn *CaptivePortalApi) TemplateDownload(fileId string) ([]byte, error) {
	var endpoint = opn.endpoint("template", "get_template")
	if fileId != "" {
		endpoint += "/" + fileId
	}
	var request, err = http.NewRequest("GET", endpoint, nil)
	if err != nil {
		return nil, err
	}
	request.Header.Set("Accept", "application/octet-stream, application/json")
	response, err := opn.Send(request)
	if err != nil {
		return nil, err
	}
	defer func() { _ = response.Body.Close() }()
	content, err := io.ReadAll(response.Body)
	if err != nil {
		return nil, err
	}
	var mediaType, _, _ = mime.ParseMediaType(response.Header.Get("Content-Type"))
	if response.StatusCode != http.StatusOK || mediaType == "application/json" || !bytes.HasPrefix(content, []byte("PK")) {
		var message = strings.TrimSpace(string(content))
		var container struct {
			Message      string `json:"message"`
			ErrorMessage string `json:"errorMessage"`
		}
		if json.Unmarshal(content, &container) == nil && container.Message+container.ErrorMessage != "" {
			message = container.Message + container.ErrorMessage
		}
		if response.StatusCode != http.StatusOK {
			return nil, &coreapi.HttpError{StatusCode: response.StatusCode, Message: message}
		}
		if len(message) > 200 {
			message = message[:200] + "..."
		}
		return nil, fmt.Errorf("expected a zip file from %s, got: %q", endpoint, message)
	}
	return content, nil
}

// TemplateValidateZip checks that content is a readable zip file with at least one file
func TemplateValidateZip(content []byte) error {
	var reader, err = zip.NewReader(bytes.NewReader(content), int64(len(content)))
	if err != nil {
		return fmt.Errorf("not a zip file: %w", err)
	}
	for _, file := range reader.File {
		if !file.FileInfo().IsDir() {
			return nil
		}
	}
	return errors.New("the zip file contains no files")
}

// TemplateSave stores a template (save_template): with uuid "" the template with this name is created, or its
// content replaced when one with exactly this name exists; with a uuid that template is renamed to name and, when
// content is given, its content replaced. content is a zip file, OPNsense strips the files equal to the default
// template. An empty content keeps the stored one
func (opn *CaptivePortalApi) TemplateSave(uuid string, name string, content []byte) error {
	if err := TemplateValidateName(name); err != nil {
		return err
	}
	var body = map[string]string{"name": name}
	if uuid != "" {
		body["uuid"] = uuid
	}
	if len(content) > 0 {
		if err := TemplateValidateZip(content); err != nil {
			return err
		}
		body["content"] = base64.StdEncoding.EncodeToString(content)
	} else if uuid == "" {
		return errors.New("a new template needs content")
	}
	var answer map[string]any
	if err := opn.DoJSON("POST", opn.endpoint("template", "save_template"), body, &answer); err != nil {
		return err
	}
	if message, failed := answer["error"]; failed {
		switch message := message.(type) {
		case string:
			if message == "node not found" {
				return &coreapi.NotFoundError{Name: templateName(uuid)}
			}
			return fmt.Errorf("OPNsense refused the template: %s", message)
		default:
			return errors.New("OPNsense refused the template (could not process the zip file)")
		}
	}
	if _, saved := answer["name"]; !saved {
		return fmt.Errorf("unexpected answer from save_template: %v", answer)
	}
	return nil
}

// TemplateRemove deletes the template with this uuid, *NotFoundError when it does not exist. OPNsense does not
// check whether zones use it
func (opn *CaptivePortalApi) TemplateRemove(uuid string) error {
	if uuid == "" || strings.Contains(uuid, ",") {
		return fmt.Errorf("cannot remove a captive portal template by uuid %q", uuid)
	}
	var _, err = opn.Mutate(fmt.Sprintf("%s/%s", opn.endpoint("template", "del_template"), uuid), nil)
	if coreapi.IsNotFound(err) {
		return &coreapi.NotFoundError{Name: templateName(uuid), Err: err}
	}
	return err
}
